<script setup lang="ts">
definePageMeta({layout:false});useSeo('Acceso del equipo','Panel privado de gestión de solicitudes de Uniformes Ellas.');
const email=ref('');const password=ref('');const busy=ref(false);const error=ref('');const {staff}=useStaff();
async function login(){if(busy.value)return;busy.value=true;error.value='';try{staff.value=await $fetch<{name:string;email:string;csrf:string;role:'admin'|'staff'}>('/api/auth/login',{method:'POST',body:{email:email.value,password:password.value}});await navigateTo('/admin/solicitudes');}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
</script>
<template><div class="login-page"><NuxtLink to="/" class="login-back"><AppIcon name="ArrowLeft" :size="17" /> Volver a la web</NuxtLink><div class="login-card"><img src="/brand/uniformes-ellas.png" alt="Uniformes Ellas" width="112" height="90" /><span class="eyebrow">ESPACIO PRIVADO DEL EQUIPO</span><h1>Todo tu equipo.<br /><span class="serif-word">Bajo control.</span></h1><p>Accede para revisar y gestionar las solicitudes.</p><form @submit.prevent="login"><label>Email<input v-model="email" type="email" autocomplete="username" required maxlength="254" /></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required maxlength="200" /></label><p v-if="error" class="alert error" role="alert">{{error}}</p><button class="button dark full" type="submit" :disabled="busy">{{busy?'Entrando…':'Entrar al panel'}}<AppIcon name="ArrowUpRight" /></button></form><span class="login-footnote"><AppIcon name="LockKeyhole" :size="14" /> Solicita tus credenciales al responsable de la demo.</span></div><span class="login-demo">DEMOSTRACIÓN COMERCIAL · UNIFORMES ELLAS</span></div></template>
